style.css:
@-moz-document domain("roblox.com") {
body, .content, .container, .section, .game-card-container, .home-container {
    background-color: #ffe6f0 !important; /* rosa pastel */
    color: #4d4d4d !important; /* texto escuro pra contraste */
  }

  .header, .navbar, .navigation-container, .home-header, .text-nav, .top-nav {
    background-color: #ffcce5 !important;
    color: #4d4d4d !important;
  }

  .btn-primary, .search-bar input, .input-field, input[type="text"], button, select {
    background-color: #ffd6eb !important;
    color: #4d4d4d !important;
    border: none !important;
  }

  .game-card, .game-card-thumb-container, .recommendation-game, .tile, .card {
    background-color: #fff0f5 !important;
    border-radius: 12px !important;
    border: 1px solid #ffb6d9 !important;
  }

  a, .text-link {
    color: #ff69b4 !important;
  }

  .notification-red, .icon-alert {
    background-color: #ff8fb1 !important;
  }

  .home-container .section-title {
    color: #ff66a3 !important;
    font-weight: bold !important;
  }

  .avatar-card-label, .text-overflow {
    color: #4d4d4d !important;
  }

  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #ffe6f0;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #ff99cc;
    border-radius: 10px;
  }
}
